import math

def entropy(ps):
    return -sum(p * math.log2(p) for p in ps if p > 0)

def mutual_information(joint):
    """I(X; Y) in bits from a table of chances or counts (a list of rows)."""
    total = sum(sum(row) for row in joint)
    cells = [c / total for row in joint for c in row]
    rows = [sum(row) / total for row in joint]
    cols = [sum(col) / total for col in zip(*joint)]
    return entropy(rows) + entropy(cols) - entropy(cells)

